/* Model creation/destruction functions */

void MODEL_mkTestGibbsPipeline::create_model(tSimStateHdl simHdl, bool master)
{
  sim_hdl = simHdl;
  init_reset_request_counters(sim_hdl);
  mkTestGibbsPipeline_instance = new MOD_mkTestGibbsPipeline(sim_hdl, "top", NULL);
  bk_get_or_define_clock(sim_hdl, "CLK");
  if (master)
  {
    bk_alter_clock(sim_hdl, bk_get_clock_by_name(sim_hdl, "CLK"), CLK_LOW, false, 0llu, 5llu, 5llu);
    bk_use_default_reset(sim_hdl);
  }
  bk_set_clock_event_fn(sim_hdl,
			bk_get_clock_by_name(sim_hdl, "CLK"),
			schedule_posedge_CLK,
			NULL,
			(tEdgeDirection)(POSEDGE));
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_0_requestQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_0_responseQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_1_requestQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_1_responseQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_2_requestQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_2_responseQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_3_requestQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_3_responseQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_4_requestQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_4_responseQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_5_requestQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_5_responseQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_6_requestQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_6_responseQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_7_requestQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_pwlLanes_7_responseQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_randomGenerator_randomQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_resultQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->INST_pipeline_logProbSegmentQ.set_clk_0)("CLK");
  (mkTestGibbsPipeline_instance->set_clk_0)("CLK");
}
void MODEL_mkTestGibbsPipeline::destroy_model()
{
  delete mkTestGibbsPipeline_instance;
  mkTestGibbsPipeline_instance = NULL;
}
void MODEL_mkTestGibbsPipeline::reset_model(bool asserted)
{
  (mkTestGibbsPipeline_instance->reset_RST_N)(asserted ? (tUInt8)0u : (tUInt8)1u);
}
void * MODEL_mkTestGibbsPipeline::get_instance()
{
  return mkTestGibbsPipeline_instance;
}

/* Fill in version numbers */
void MODEL_mkTestGibbsPipeline::get_version(char const **name, char const **build)
{
  *name = "2026.01";
  *build = "9bd39e6f";
}

/* Get the model creation time */
time_t MODEL_mkTestGibbsPipeline::get_creation_time()
{
  
  /* Sun Aug 23 16:07:06 UTC 2026 */
  return 1787501226llu;
}

/* State dumping function */
void MODEL_mkTestGibbsPipeline::dump_state()
{
  (mkTestGibbsPipeline_instance->dump_state)(0u);
}

/* VCD dumping functions */
MOD_mkTestGibbsPipeline & mkTestGibbsPipeline_backing(tSimStateHdl simHdl)
{
  static MOD_mkTestGibbsPipeline *instance = NULL;
  if (instance == NULL)
  {
    vcd_set_backing_instance(simHdl, true);
    instance = new MOD_mkTestGibbsPipeline(simHdl, "top", NULL);
    vcd_set_backing_instance(simHdl, false);
  }
  return *instance;
}
void MODEL_mkTestGibbsPipeline::dump_VCD_defs()
{
  (mkTestGibbsPipeline_instance->dump_VCD_defs)(vcd_depth(sim_hdl));
}
void MODEL_mkTestGibbsPipeline::dump_VCD(tVCDDumpType dt)
{
  (mkTestGibbsPipeline_instance->dump_VCD)(dt,
					   vcd_depth(sim_hdl),
					   mkTestGibbsPipeline_backing(sim_hdl));
}
